sys_script_include.script:
var TomekToolbox = Class.create();
TomekToolbox.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getShortDescription: function() {
        var incidentNumber = this.getParameter('sysparm_number');		
        var gr = new GlideRecord('incident');
        gr.addQuery('number', incidentNumber);
        gr.query();
        if (gr.next()) {
            return gr.getValue('short_description') || '';  // Null-safe
        }
        return '';  // Zawsze return coś (dla GlideAjax)
    },
    type: 'TomekToolbox'
});
